vertexShaderInstructions:
uniform mat4 renderer_MVPMat;
attribute vec4 POSITION;

varying vec4 positionCS;

void main() { 
positionCS = renderer_MVPMat * POSITION ;
gl_Position = positionCS ;
 }

uniform mat4 renderer_MVPMat;
uniform mat4 renderer_NormalMat;
attribute vec4 POSITION;
attribute vec3 NORMAL;

varying vec3 normalWS;

void main() { 
normalWS = mat3 ( renderer_NormalMat ) * NORMAL ;
gl_Position = renderer_MVPMat * POSITION ;
 }

fragmentShaderInstructions:
uniform mat4 camera_ViewMat;
uniform float material_ScreenSpaceReflectionMode;
varying vec3 normalWS;


vec2 encodeLegacyViewNormal ( vec3 normal ) { normal /= max ( abs ( normal.x ) + abs ( normal.y ) + abs ( normal.z ) , 0.000001 ) ;
vec2 encoded = normal.xy ;
if ( normal.z < 0.0 ) { encoded = ( 1.0 - abs ( encoded.yx ) ) * vec2 ( encoded.x >= 0.0 ? 1.0 : - 1.0 , encoded.y >= 0.0 ? 1.0 : - 1.0 ) ; }
return encoded * 0.5 + 0.5 ; }
void main() { if ( material_ScreenSpaceReflectionMode < 0.5 ) discard ;
vec3 viewNormal = normalize ( mat3 ( camera_ViewMat ) * normalWS ) ;

gl_FragData[0] = vec4 ( encodeLegacyViewNormal(viewNormal) , 0.1 , 1.0 ) ;
gl_FragData[1] = vec4 ( 1.0 ) ;
 }
